final class Fake implements Backend {
    public array $states=[];public array $sent=[];public bool $fail=false;public int $limit=2;
    public function identity(string $token):?array{return in_array($token,['omcp_'.str_repeat('a',64),'omcp_'.str_repeat('b',64)],true)?['id'=>hash('sha256',$token),'email'=>($token[5]==='a'?'verified@example.org':'other@example.org')]:null;}
