$p=calltool('prepare_correspondence',$draft);check($p['status']==='prepared_not_sent'&&!isset($p['ticket'])&&count($b->sent)===0,'public preview no send token');$p=calltool('prepare_correspondence',$draft,$auth);check(isset($p['ticket'])&&$p['reply_to']==='verified@example.org','authenticated preparation');$send=$draft+['ticket'=>$p['ticket'],'approved'=>true];
