check(calltool('send_correspondence',$send,$auth)['status']==='accepted_by_mail_service','authorized send');check($b->sent[0]===['verified@example.org','Test subject','Test body'],'verified Reply-To and exact content');check(calltool('send_correspondence',$send,$auth)['status']==='already_accepted'&&count($b->sent)===1,'replay no duplicate mail');
